Scripts.OnMouseUp:
if ( button == "LeftButton" ) then
	PlaySound("igMainMenuOptionCheckBoxOn");
	self:GetParent():GetParent():GetParent():SelectSetFromButton(self.setID);
elseif ( button == "RightButton" ) then
	if ( RebuffedMenu:IsOpen(self) ) then
		RebuffedMenu:Close(self);
		return;
	end
	local scrollFrame = self:GetParent():GetParent();
	RebuffedMenu:Open(self, scrollFrame:GetFavoriteMenuEntries(self.setID), nil, "LEFT");
	PlaySound("igMainMenuOptionCheckBoxOn");
end

Scripts.OnUpdate:
if ( self:IsMouseOver() ) then
	self:SetAlpha(0);
else
	self:SetAlpha(abs(mod(GetTime(), 2) - 1));
end

Scripts.OnLoad:
-- The era replaces an inherited handler rather than chaining it, so the
-- art template's own OnLoad never runs here.
MixinAndLoadScripts(self, "DropdownButtonArtMixin");
self:UpdateArt();

Scripts.OnLeave:
if ( not self:GetParent():IsMouseOver() ) then
	self:Hide();
end
